mapper.sql:
WHERE sys_notification.receiver = #{request.receiver} and sys_notification.organization_id = #{organizationId}

    AND ( sys_notification.subject LIKE CONCAT('%', #{request.subject},'%') OR sys_notification.content LIKE CONCAT('%', #{request.subject},'%') )


    AND ( (sys_notification.subject LIKE  CONCAT('%', #{request.keyword},'%') and sys_notification.type = 'ANNOUNCEMENT_NOTICE') OR (sys_notification.resource_name LIKE  CONCAT('%', #{request.keyword},'%') and sys_notification.type = 'SYSTEM_NOTICE'))


    AND sys_notification.type = #{request.type}




          AND (sys_notification.trigger_type = 'MENTION' OR LOCATE('MENTION', sys_notification.operation) > 0)


          AND sys_notification.trigger_type IN ('FOLLOW_UP_RECORD_COMMENT_MENTIONED', 'FOLLOW_UP_PLAN_COMMENT_MENTIONED', 'APPROVAL_COMMENT_MENTIONED')


          AND sys_notification.trigger_type = #{request.triggerType}




    AND sys_notification.operation = #{request.operation}


    AND sys_notification.create_time >= #{request.createTime}


    AND sys_notification.create_time >= #{request.createTime} AND sys_notification.create_time <= #{request.endTime}

mapper.select:
SELECT * FROM sys_notification


    AND sys_notification.status = #{request.status}


    AND () = #{request.resourceType}

ORDER BY sys_notification.status DESC, sys_notification.create_time DESC

